"""Monta a edição básica a partir dos textos autorais; não altera banco ou publicação."""
import json, runpy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
COURSES=runpy.run_path(str(ROOT/'autoria/conteudo.py'))['COURSES']
CASES=runpy.run_path(str(ROOT/'autoria/casos.py'))['CASES']
grade=json.loads((ROOT/'grade-editorial-24-cursos.json').read_text())
out=ROOT/'basico';out.mkdir(exist_ok=True)
manifest=[]
titles=['Sales Fundamentals','SDR','Cold Calling in Practice','WhatsApp for Sales','Email and LinkedIn Prospecting','Instagram and Social Selling','Lists, ICP and Qualification','Discovery and Consultative Selling','Objections','Follow-up and Re-engagement','Presentations and Proposals','Challenger 1 — Teach','Challenger 2 — Tailor','Challenger 3 — Take Control','Closer','BDR — Enterprise Accounts','Door-to-Door Sales','Sales Management','CRM, Routine and Metrics','AI for Salespeople','Ethics, LGPD and Responsible Contact','Selling to the US and India','Selling in Healthcare, Education and Digital Products','B2B Services Sales']
for c in grade['courses']:
 cid=c['id'];folder=out/f'{cid:02}';folder.mkdir(exist_ok=True)
 for locale in ['pt-BR','en-US','en-IN']:
  pt=locale=='pt-BR';lang='pt' if pt else 'en';title=c['name'] if pt else titles[cid-1]
  modules=[];assessment=[];n=0
  if cid==1:
   full=json.loads((ROOT/'cursos/01-fundamentos'/f'{locale}.json').read_text())
   case_text=('Oficina fictícia precisa organizar pedidos; problema, orçamento e decisão devem ser confirmados.' if pt else 'A fictional workshop needs to organise orders; verify the problem, funding and decision process.')
   task=('Conduza um primeiro atendimento e registre fatos, lacunas e próximo passo.' if pt else 'Conduct an initial conversation and record facts, gaps and next step.')
   key=('Identifique-se, investigue sem presumir, confirme aderência e respeite recusa. Não prometa resultados.' if pt else 'Identify yourself, investigate without assumptions, verify fit and respect refusal. Promise no results.')
  else:
   case=CASES[cid];case_text=case[lang]
   if not pt:case_text+='\n\n'+case['us' if locale=='en-US' else 'india']
   task=case['task_'+lang];key=case['key_'+lang]
  for mi,m in enumerate(c['modulos']):
   lessons=[]
   for ai,a in enumerate(m['aulas']):
    if cid==1:
     old=full['modulos'][mi]['aulas'][ai];lesson_title=old['titulo'];body=old['texto_apoio'];script=old['roteiro_video']['fala_instrutor'];exercise=old['exercicio']
    else:
     atom=COURSES[cid][n];lesson_title=a['titulo'] if pt else atom['title_en'];body=atom[lang]
     script=(f'Nesta aula, vamos trabalhar {lesson_title.lower()}. '+body+' Pause e aplique esse princípio ao caso do curso. Explique qual informação sustenta sua decisão e o que ainda precisa ser confirmado.' if pt else f'In this lesson we explore {lesson_title.lower()}. '+body+' Pause and apply this principle to the course case. Explain what supports your decision and what still needs verification.')
     exercise={'instrucoes':([f'Aplique “{lesson_title}” ao caso fictício do curso.','Escreva uma ação adequada, um erro a evitar e uma informação ainda desconhecida.','Justifique com o princípio desta aula; não invente fatos do cliente.'] if pt else [f'Apply “{lesson_title}” to the fictional course case.','Write one appropriate action, one mistake to avoid and one remaining unknown.','Justify using this lesson; do not invent buyer facts.']), 'gabarito':body,'justificativa':('A resposta deve seguir o princípio, preservar os fatos do caso e reconhecer lacunas. Outras formulações são válidas quando justificadas; não há obrigação de repetir as palavras do modelo.' if pt else 'The response must follow the principle, preserve case facts and recognise gaps. Justified alternatives are acceptable; exact wording is not required.')}
    lessons.append({'id':a['id'],'titulo':lesson_title,'tipo':'texto','conteudo':body,'roteiro_video':script,'exercicio':exercise,'duracaoMin_planejada':a['duracaoMin'],'status':'basico_para_revisao'})
    n+=1
   module_title=m['titulo'] if pt else f'Module {mi+1}: '+lessons[0]['titulo']
   modules.append({'id':m['id'],'titulo':module_title,'titulo_original_pt':m['titulo'],'duracaoMin_planejada':m['duracaoMin'],'aulas':lessons})
   assessment.append({'id':f'{cid:02}-M{mi+1}','pergunta':(f'No caso do curso, como você aplicaria o módulo “{module_title}”? Apresente uma decisão, a evidência disponível e uma lacuna.' if pt else f'How would you apply “{module_title}” to the course case? Give one decision, supporting evidence and an unknown.'),'criterios_correcao':[x['conteudo'] for x in lessons],'pontos':20,'justificativa':('Avaliar coerência com o módulo e fidelidade ao caso. Não pontuar certeza inventada ou ação fora da autorização.' if pt else 'Assess consistency with the module and case. Do not reward invented certainty or unauthorised action.')})
  assessment.append({'id':f'{cid:02}-FINAL','pergunta':task,'resposta_modelo':key,'pontos':20,'justificativa':('O projeto integra os módulos; avaliar a decisão e seus limites, não apenas a fluência da apresentação.' if pt else 'The project integrates the modules; assess the decision and its limits, not merely presentation fluency.')})
  sim={'status':'roteiro_para_pratica; integracao_ia_pendente','instrucao_ator':('Interprete o cliente do caso fictício. Revele somente fatos fornecidos quando perguntado; para lacunas, diga que precisa verificar. Não ensine nem atribua nota durante o diálogo. Depois de três turnos, apresente uma dúvida sobre prazo ou escopo; na segunda rodada, peça encerramento do contato.' if pt else 'Play the fictional buyer. Reveal supplied facts when asked; say you need to verify unknowns. Do not teach or score during dialogue. After three turns raise a timing or scope concern; in a second round request closure.'),'instrucao_avaliador':('Use somente a transcrição e a rubrica. Cite evidências, indique lacunas e peça revisão humana quando a nota for incerta. Não emitir certificado ou aprovar contratação.' if pt else 'Use only the transcript and rubric. Cite evidence, identify gaps and request human review for uncertain scores. Do not issue certificates or approve contracts.'),'rubrica':[{'criterio':label,'pontos':20} for label in (['Identificação e clareza','Investigação e escuta','Aplicação do conteúdo e aderência','Próximo passo e registro','Ética e privacidade'] if pt else ['Identity and clarity','Discovery and listening','Content application and fit','Next step and record','Ethics and privacy'])],'ancoras':{'0':'Ausente ou contradiz o caso / Absent or contradicts the case','10':'Parcial, com lacunas / Partial, with gaps','20':'Demonstrado com evidência / Demonstrated with evidence'},'falhas_criticas':['Promessa de resultado garantido / Guaranteed outcomes','Falsificação / Fabrication','Insistência após recusa / Evading refusal','Exposição indevida de dados / Improper data disclosure']}
  doc={'schema_version':'2.0-basico','id':c['slug'],'course_number':cid,'locale':locale,'titulo':title,'nivel_original':c['level'],'certificacao_planejada':c['certification'],'carga_horaria_planejada_h':c['hours'],'edicao':'basica_completa_para_revisao','nota_carga':('Carga preservada da grade; esta edição enxuta não comprova esse tempo de estudo. Validar e aprofundar antes de certificar horas.' if pt else 'Planned curriculum hours are preserved; this concise edition does not establish actual study time. Validate and expand before certifying hours.'),'modulos':modules,'caso':{'natureza':'ficticio / fictional','texto':case_text},'projeto':{'instrucoes':task,'gabarito':key},'avaliacao_basica':{'tipo':'discursiva_com_rubrica','questoes':assessment,'total_pontos':100,'minimo_sugerido':80,'observacao':'Não substitui banco profissional de 40 questões / Does not replace a 40-question professional bank'},'simulacao':sim,'revisoes':{'pedagogica':'pendente','juridica_privacidade':'pendente','ingles_local':'pendente' if not pt else 'nao_aplicavel','gravacao':'pendente','publicacao':'nao_realizada'},'proximas_etapas':['Aprofundamento / Expansion','Fontes e estatísticas por curso / Course-specific research','Banco profissional de 40 questões quando aplicável / Professional question bank where applicable','Revisão humana / Human review','Integração e gravação / Integration and recording']}
  (folder/f'{locale}.json').write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n')
  md=[f'# {title} — {locale}','','Edição básica para revisão. / Basic review edition.','','**Carga planejada:** '+str(c['hours'])+'h. '+doc['nota_carga'],'','## Caso fictício / Fictional case','',case_text,'']
  for m in modules:
   md += ['## '+m['titulo'],'']
   for a in m['aulas']:
    md += ['### '+a['id']+' — '+a['titulo'],'','**Aula / Lesson**',a['conteudo'],'','**Roteiro / Script**',a['roteiro_video'],'','**Exercício / Exercise**']+[f'{i+1}. {s}' for i,s in enumerate(a['exercicio']['instrucoes'])]+['','**Resposta comentada / Answer guide**',a['exercicio']['gabarito'],'',a['exercicio']['justificativa'],'']
  md+=['## Projeto / Project','',task,'','**Resposta-modelo / Model answer**',key,'','## Avaliação básica / Basic assessment','','5 atividades discursivas, 20 pontos cada. / 5 written tasks, 20 points each.','']
  for q in assessment:md += ['- '+q['pergunta']]
  md+=['','Correção: use os princípios do módulo e o gabarito do projeto. / Mark against module principles and the project key.','','## Simulação / Role-play','',sim['instrucao_ator'],'',sim['instrucao_avaliador'],'']+[f"- {r['criterio']}: {r['pontos']} pontos/points" for r in sim['rubrica']]+['','0: ausente / absent; 10: parcial / partial; 20: demonstrado / demonstrated. Falha crítica impede aprovação prática / Critical failures prevent a practical pass.','','## Pendências / Pending work','','Revisão pedagógica, jurídica e local; aprofundamento, gravação e integração. Bancos profissionais de 40 questões continuam pendentes. / Instructional, legal and local review; expansion, recording and integration. Professional 40-question banks remain pending.','']
  (folder/f'{locale}.md').write_text('\n'.join(md))
 manifest.append({'id':cid,'titulo':c['name'],'horas_planejadas':c['hours'],'aulas':sum(len(m['aulas']) for m in modules),'status':'basico_escrito','locales':['pt-BR','en-US','en-IN'],'pasta':f'{cid:02}'})
index=['# RYCS Academy — 24 cursos, edição básica','','Os 24 cursos têm uma versão básica escrita em português e inglês contextualizado para EUA e Índia. Cada arquivo reúne aulas curtas, roteiro, exercício com resposta, caso fictício, projeto, avaliação discursiva e roteiro de simulação.','','As 134h continuam como planejamento da grade. A versão enxuta não comprova essa duração. Aprofundamento, bancos profissionais de 40 questões, revisão humana e gravação permanecem pendentes.','','As aulas entram no app sozinhas quando o servidor inicia (`server/services/academyBasico.js`), uma única vez e só nos cursos globais que ainda não têm módulos, aulas nem questões. Preço, status e textos editados pelo administrador não mudam, então um curso em rascunho continua fora da vitrine. Sem questões, o curso aparece como estudo sem certificado.','','| Curso | Aulas | Horas planejadas | Português | EUA | Índia |','|---|---:|---:|---|---|---|']
for c in manifest:
 d=c['pasta'];index.append(f"| {c['id']:02} · {c['titulo']} | {c['aulas']} | {c['horas_planejadas']} | [Ler]({d}/pt-BR.md) | [Read]({d}/en-US.md) | [Read]({d}/en-IN.md) |")
index+=['','Os JSON ficam ao lado de cada documento. São dados editoriais para integração futura, não um comando de atualização do banco. Preserve preços, permissões e progresso ao implementar a importação. Os arquivos do instrutor contêm respostas e não devem ser expostos como prova antes da tentativa.','']
(out/'LEIA-ME.md').write_text('\n'.join(index))
(out/'manifesto.json').write_text(json.dumps({'edicao':'basica','total_cursos':24,'total_horas_planejadas':134,'total_aulas':sum(c['aulas'] for c in manifest),'cursos':manifest,'publicado':False},ensure_ascii=False,indent=2)+'\n')
(ROOT/'LEIA-ME.md').write_text('# RYCS Sales Academy\n\n[Abra os 24 cursos — edição básica](basico/LEIA-ME.md).\n\nA edição básica está escrita nos três contextos. Aprofundamento, bancos profissionais de 40 questões, revisões e gravação continuam pendentes. As aulas básicas entram no app quando o servidor inicia, só nos cursos que ainda estão vazios. As 134h são planejadas, não duração comprovada pela edição enxuta.\n\n[Fundamentos — versão anterior ampliada](cursos/01-fundamentos/revisao-pt-BR.md).\n')
(ROOT/'producao.json').write_text(json.dumps({'edicao':'basica','basico_concluido':True,'todos_ultradetalhados':False,'cursos_basicos_escritos':list(range(1,25)),'locales':['pt-BR','en-US','en-IN'],'total_aulas_por_locale':436,'horas_planejadas':134,'bancos_profissionais_40_questoes':'pendente','revisao_humana':'pendente','gravacao':'pendente','publicacao':'nao_realizada'},ensure_ascii=False,indent=2)+'\n')
print('Montados 24 cursos × 3 versões: 72 documentos e 72 JSON.')
